import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`funnel-teardown`,heroTitle:`Tear down any competitor's funnel in minutes`,heroSubtitle:`Perplexity Computer walks your competitor's entire funnel, maps every step from ad to checkout, and delivers a teardown report — automatically.`,inputUrlCta:`Tear down this funnel`,inputUrlPlaceholder:`competitor-site.com`,inputUrlPrefill:`Go to {url} and perform a complete funnel teardown of this competitor. 1) Identify and walk every stage of their customer funnel — from landing pages and lead magnets to signup flows, onboarding sequences, pricing pages, and checkout. 2) Screenshot and document each step, noting copy, CTAs, form fields, trust signals, urgency tactics, and design patterns. 3) Identify upsells, cross-sells, downsells, and post-purchase flows if visible. 4) Analyze their email capture strategy and any visible retargeting or nurture sequences. 5) Map the full funnel visually — stage by stage with conversion intent at each step. 6) Score each funnel stage on persuasion, friction, and clarity. 7) Deliver a competitive teardown report with specific takeaways you can steal, gaps you can exploit, and recommendations to outperform this funnel in your own marketing.`,heroOverlaySteps:[`Walking your competitor's funnel from landing page to checkout`,`Capturing screenshots, copy, CTAs, and conversion tactics at every step`,`Scoring each stage on persuasion, friction, and clarity`,`Full funnel map, teardown scores, and steal-worthy tactics — ready to review`],generatingSteps:[`Visiting {url} to identify every funnel stage from entry to conversion`,`Designing an agent to walk each step, capture screenshots, and document conversion tactics`,`Configuring scoring for persuasion, friction, and clarity at every funnel stage`,`Setting up your teardown report with visual funnel map and actionable takeaways`],featureSectionTitle:`From competitor URL to funnel playbook`,featureCardTitles:[`Connects to your intel stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Notion, Google Sheets, Google Drive, Slack, Airtable — Computer delivers teardown reports and funnel maps straight into the tools your team already uses.`,`Stage-by-stage funnel maps. Annotated screenshots. Persuasion and friction scores. Copy teardowns. A prioritized list of tactics to steal and gaps to exploit.`],capabilitySectionTitle:`Your competitive intel team, on autopilot`,capabilitySectionSubtitle:`Paste a competitor URL, step away, come back to a complete funnel teardown.`,capabilityCards:[{title:`Full Funnel Walk`,description:`Computer can navigate every step of a competitor's funnel — landing pages, signup forms, onboarding flows, pricing, and checkout — capturing everything along the way.`},{title:`Conversion Tactics`,description:`Computer can identify urgency triggers, trust signals, social proof, upsells, and CTA patterns — and explain why each tactic works or falls flat.`},{title:`Funnel Scoring`,description:`Computer can score every funnel stage on persuasion, friction, and clarity — so you see exactly where competitors convert and where they leak.`},{title:`Connect Your Tools`,description:`Computer can push teardown reports to Notion, Google Sheets, Slack, and Airtable — build workflows across your entire competitive intel stack.`},{title:`Track Over Time`,description:`Computer can remember past teardowns across sessions — so you can track how competitors evolve their funnels and spot new tactics early.`},{title:`Monitor & Alert`,description:`Computer can re-analyze competitor funnels weekly and alert you when they change pricing, swap CTAs, or launch new conversion flows.`}]});export{t as default};
